export type SortableBaseItem = { id: string };

export interface SortableConfig {
  handle?: boolean;
  /**
   * "list" (default) — vertical strategy + axis lock.
   * "grid" — rect strategy, free-form drag in both axes.
   */
  layout?: "list" | "grid";
}

export interface SortableContextValue {
  activeId: string | null;
  config: SortableConfig;
}

import * as React from "react";
import type { SortableContextValue } from "./types";

export const SortableCtx = React.createContext<SortableContextValue | null>(
  null,
);

export function useSortableCtx(): SortableContextValue {
  const ctx = React.useContext(SortableCtx);
  if (!ctx) throw new Error("useSortableCtx must be used inside SortableRoot");
  return ctx;
}

export const SortableHandleCtx = React.createContext<
  Record<string, React.EventHandler<React.SyntheticEvent>> | undefined
>(undefined);

import * as React from "react";
import {
  DndContext,
  closestCenter,
  PointerSensor,
  KeyboardSensor,
  useSensor,
  useSensors,
  DragOverlay,
  type DragStartEvent,
  type DragEndEvent,
} from "@dnd-kit/core";
import {
  SortableContext,
  sortableKeyboardCoordinates,
  verticalListSortingStrategy,
  rectSortingStrategy,
  arrayMove,
} from "@dnd-kit/sortable";
import { restrictToVerticalAxis } from "@dnd-kit/modifiers";
import { SortableCtx } from "./sortable-context";
import type { SortableBaseItem, SortableConfig } from "./types";

export interface SortableRootProps<T extends SortableBaseItem> {
  items: T[];
  onReorder: (items: T[]) => void;
  config?: SortableConfig;
  renderOverlay?: (item: T) => React.ReactNode;
  children: React.ReactNode;
}

export function SortableRoot<T extends SortableBaseItem>({
  items,
  onReorder,
  config = {},
  renderOverlay,
  children,
}: SortableRootProps<T>) {
  const [activeId, setActiveId] = React.useState<string | null>(null);

  const isGrid = config.layout === "grid";

  const sensors = useSensors(
    useSensor(PointerSensor, { activationConstraint: { distance: 4 } }),
    useSensor(KeyboardSensor, {
      coordinateGetter: sortableKeyboardCoordinates,
    }),
  );

  const activeItem = activeId
    ? (items.find((i) => i.id === activeId) ?? null)
    : null;

  function onDragStart({ active }: DragStartEvent) {
    setActiveId(active.id as string);
  }

  function onDragEnd({ active, over }: DragEndEvent) {
    setActiveId(null);
    if (!over || active.id === over.id) return;
    const from = items.findIndex((i) => i.id === active.id);
    const to = items.findIndex((i) => i.id === over.id);
    onReorder(arrayMove(items, from, to));
  }

  return (
    <SortableCtx.Provider value={{ activeId, config }}>
      <DndContext
        sensors={sensors}
        collisionDetection={closestCenter}
        modifiers={isGrid ? [] : [restrictToVerticalAxis]}
        onDragStart={onDragStart}
        onDragEnd={onDragEnd}
        onDragCancel={() => setActiveId(null)}
      >
        <SortableContext
          items={items.map((i) => i.id)}
          strategy={isGrid ? rectSortingStrategy : verticalListSortingStrategy}
        >
          {children}
        </SortableContext>

        {renderOverlay && (
          <DragOverlay dropAnimation={{ duration: 160, easing: "ease" }}>
            {activeItem ? renderOverlay(activeItem) : null}
          </DragOverlay>
        )}
      </DndContext>
    </SortableCtx.Provider>
  );
}

SortableRoot.displayName = "SortableRoot";

import * as React from "react";
import { useSortable } from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";
import { cn } from "@/lib/utils";
import { SortableCtx, SortableHandleCtx } from "./sortable-context";

export interface SortableItemProps {
  id: string;
  children: React.ReactNode;
  className?: string;
  disabled?: boolean;
  /**
   * When true, only <SortableHandle> inside this item triggers drag.
   * Overrides the SortableRoot config.handle setting for this item.
   */
  handle?: boolean;
}

type DraggableListeners = Record<string, (event: React.SyntheticEvent) => void>;

export function SortableItem({
  id,
  children,
  className,
  disabled,
  handle: handleProp,
}: SortableItemProps) {
  const { config, activeId } = React.useContext(SortableCtx)!;
  const useHandle = handleProp ?? config.handle ?? false;

  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
    isDragging,
  } = useSortable({ id, disabled });

  const style: React.CSSProperties = {
    transform: CSS.Transform.toString(transform),
    transition,
  };

  return (
    <SortableHandleCtx.Provider
      value={
        useHandle ? (listeners as unknown as DraggableListeners) : undefined
      }
    >
      <div
        ref={setNodeRef}
        style={style}
        data-dragging={isDragging || undefined}
        data-active={activeId === id || undefined}
        className={cn(
          "touch-none select-none",
          isDragging && "opacity-40",
          className,
        )}
        {...attributes}
        {...(!useHandle ? listeners : {})}
      >
        {children}
      </div>
    </SortableHandleCtx.Provider>
  );
}

SortableItem.displayName = "SortableItem";

import * as React from "react";
import { IconGripVertical } from "@tabler/icons-react";
import { cn } from "@/lib/utils";
import { SortableHandleCtx } from "./sortable-context";

export interface SortableHandleProps {
  className?: string;
  children?: React.ReactNode;
}

/**
 * Place inside <SortableItem handle> to restrict dragging to this element.
 * Renders a grip icon by default; pass children to customise.
 */
export function SortableHandle({ className, children }: SortableHandleProps) {
  const listeners = React.useContext(SortableHandleCtx);

  return (
    <button
      type="button"
      aria-label="Drag to reorder"
      className={cn(
        "cursor-grab active:cursor-grabbing p-1 rounded",
        "text-muted-foreground/40 hover:text-muted-foreground",
        "transition-colors touch-none focus-visible:outline-none",
        "focus-visible:ring-1 focus-visible:ring-primary",
        className,
      )}
      {...(listeners ?? {})}
    >
      {children ?? <IconGripVertical size={14} strokeWidth={1.8} />}
    </button>
  );
}

SortableHandle.displayName = "SortableHandle";

import * as React from "react";
import { arrayMove } from "@dnd-kit/sortable";
import type { SortableBaseItem } from "./types";

export interface UseSortableListReturn<T extends SortableBaseItem> {
  items: T[];
  setItems: React.Dispatch<React.SetStateAction<T[]>>;
  reorder: (from: string, to: string) => void;
  insert: (item: T, atIndex?: number) => void;
  remove: (id: string) => void;
  update: (id: string, patch: Partial<Omit<T, "id">>) => void;
  move: (id: string, direction: "up" | "down") => void;
}

export function useSortableList<T extends SortableBaseItem>(
  initial: T[],
): UseSortableListReturn<T> {
  const [items, setItems] = React.useState<T[]>(initial);

  const reorder = React.useCallback((from: string, to: string) => {
    setItems((prev) => {
      const fi = prev.findIndex((i) => i.id === from);
      const ti = prev.findIndex((i) => i.id === to);
      if (fi === -1 || ti === -1) return prev;
      return arrayMove(prev, fi, ti);
    });
  }, []);

  const insert = React.useCallback((item: T, atIndex?: number) => {
    setItems((prev) => {
      const next = [...prev];
      next.splice(atIndex ?? next.length, 0, item);
      return next;
    });
  }, []);

  const remove = React.useCallback((id: string) => {
    setItems((prev) => prev.filter((i) => i.id !== id));
  }, []);

  const update = React.useCallback(
    (id: string, patch: Partial<Omit<T, "id">>) => {
      setItems((prev) =>
        prev.map((i) => (i.id === id ? { ...i, ...patch } : i)),
      );
    },
    [],
  );

  const move = React.useCallback((id: string, direction: "up" | "down") => {
    setItems((prev) => {
      const idx = prev.findIndex((i) => i.id === id);
      if (idx === -1) return prev;
      const next = direction === "up" ? idx - 1 : idx + 1;
      if (next < 0 || next >= prev.length) return prev;
      return arrayMove(prev, idx, next);
    });
  }, []);

  return { items, setItems, reorder, insert, remove, update, move };
}

export { SortableRoot } from "./sortable-root";
export { SortableItem } from "./sortable-item";
export { SortableHandle } from "./sortable-handle";
export { useSortableList } from "./sortable-hook";
export type { SortableBaseItem, SortableConfig } from "./types";
